const eligible=['member','coach','clubManager','staff','accountant'];
export const workspaceRole=state=>state.identity?(state.identity.permissions.includes('platform.admin')?'admin':state.identity.permissions.includes('club.finance.read')?'gym':state.identity.permissions.includes('coach.programs')?'coach':'athlete'):state.me.role;

export function identityPage({state,t,h,btn}){
  const a=state.identity;if(!a)return '';
  const has=p=>a.permissions.includes(p);
  const role=r=>t('identity_'+r);
  const contexts=a.contexts.map(c=>`<button class="card identity-context ${a.active?.key===c.key?'active':''}" data-action="identitySwitch" data-id="${h(c.key)}" aria-pressed="${a.active?.key===c.key}"><b>${role(c.role)}</b><small>${h(c.clubName||t('identityPersonal'))}</small>${a.active?.key===c.key?`<span class="badge green">${t('identityActive')}</span>`:''}</button>`).join('');
  const inviteForm=has('club.assign')||has('platform.assign')?`<section class="card stack"><h2>${t('identityInvite')}</h2><form class="stack" data-form="identity"><input type="hidden" name="operation" value="invite"><input type="hidden" name="clubId" value="${h(a.club?.id||'')}"><label>${t('name')}<select name="target" required><option value="">${t('choosePeople')}</option>${state.profiles.filter(p=>p.id!==state.me.id).map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label><label>${t('role')}<select name="role">${(has('club.assign')?eligible:['moderator']).map(r=>`<option value="${r}">${role(r)}</option>`).join('')}</select></label><button class="primary" type="submit">${t('identityInvite')}</button></form></section>`:'';
  const invitationRows=a.invitations.filter(v=>v.status==='pending').map(v=>`<div class="rule row wrap"><div class="grow"><b>${role(v.role)}</b><br><small>${h(v.clubName||t('identityPlatform'))} · ${h(v.targetName||'')}</small></div>${v.target===state.me.id?btn(t('accept'),'identityResponse',`data-id="${h(v.id)}" data-accept="true"`,'primary')+btn(t('decline'),'identityResponse',`data-id="${h(v.id)}" data-accept="false"`,'secondary'):''}</div>`).join('');
  const roster=has('club.roster')||has('platform.assign')?`<section class="card stack"><h2>${t(has('club.roster')?'identityRoster':'identityAssignments')}</h2>${(has('club.roster')?a.roster:a.platformAssignments).map(g=>`<div class="rule row wrap"><div class="grow"><b>${h(g.name)}</b><br><small>${role(g.role)}</small></div>${(has('club.assign')||has('platform.assign'))&&g.role!=='clubOwner'&&g.userId!==state.me.id?btn(t('identityRevoke'),'identityRevoke',`data-id="${h(g.id)}"`,'secondary'):''}</div>`).join('')||`<p class="muted">${t('noItems')}</p>`}</section>`:'';
  const reports=has('platform.moderate')?`<section class="card stack"><h2>${t('reports')}</h2>${a.reportList.map(r=>`<div class="rule row wrap"><div class="grow"><p>${h(r.reason)}</p>${r.evidence?.text?`<blockquote class="report-excerpt">${h(r.evidence.text)}</blockquote>`:''}</div>${btn(t('resolve'),'identityResolve',`data-id="${h(r.id)}"`,'secondary')}</div>`).join('')||`<p class="muted">${t('noItems')}</p>`}</section>`:'';
  const create=state.me.role==='gym'&&state.me.verified?`<section class="card stack"><h2>${t('identityCreateClub')}</h2><form class="stack" data-form="identity"><input type="hidden" name="operation" value="createClub"><label>${t('name')}<input name="name" required minlength="2" maxlength="80"></label><button class="primary" type="submit">${t('create')}</button></form></section>`:'';
  return `<div class="stack"><div class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / IDENTITY</span><h1>${t('identity')}</h1><p>${t('identityIntro')}</p></div><section class="card stack"><h2>${t('identityContexts')}</h2><div class="grid workspace-grid">${contexts}</div></section>${a.club?`<section class="card row space"><div><small>${t('identityCurrentClub')}</small><h2>${h(a.club.name)}</h2></div><span class="badge green">${role(a.active.role)}</span></section>`:''}<section class="card stack"><h2>${t('identityInvitations')}</h2>${invitationRows||`<p class="muted">${t('noItems')}</p>`}</section>${roster}${inviteForm}${create}${reports}</div>`;
}
